/* In the vulnerable code, the ID transformation logic had issues with 
   reverse mapping when more than UID_GID_MAP_MAX_BASE_EXTENTS (5) ranges were present */

/* The fix involved correcting the map_id_range_down() function and 
   improving the reverse mapping logic in sort_idmaps() */

static u32 map_id_range_down(struct uid_gid_map *map, u32 id, u32 count)
{
    unsigned idx, extents;
    u32 first, last, id2;

    id2 = id + count - 1;

    /* Find the matching extent */
    extents = map->nr_extents;
    smp_rmb();
    for (idx = 0; idx < extents; idx++) {
        first = map->extent[idx].first;
        last = first + map->extent[idx].count - 1;
        if (id >= first && id <= last &&
            (id2 >= first && id2 <= last))
            break;
    }
    /* Map the id or note failure */
    if (idx < extents)
        id = (id - first) + map->extent[idx].lower_first;
    else
        id = (u32) -1;

    return id;
}

/* The critical fix was in the sort_idmaps() function to properly handle
   reverse mapping when nr_extents > UID_GID_MAP_MAX_BASE_EXTENTS */

static int sort_idmaps(struct uid_gid_map *map)
{
    if (map->nr_extents <= UID_GID_MAP_MAX_BASE_EXTENTS) {
        sort(map->extent, map->nr_extents, sizeof(map->extent[0]),
             cmp_extents, NULL);
        /* The reverse map is only needed when there are more than
         * UID_GID_MAP_MAX_BASE_EXTENTS extents.
         */
        return 0;
    }

    /* Sort forward array by first */
    sort(map->forward, map->nr_extents, sizeof(map->forward[0]),
         cmp_extents_forward, NULL);
    /* Sort reverse array by lower_first */
    sort(map->reverse, map->nr_extents, sizeof(map->reverse[0]),
         cmp_extents_reverse, NULL);

    /* Verify that the reverse map and forward map are consistent */
    for (idx = 0; idx < map->nr_extents; idx++) {
        if (map->forward[idx].lower_first != map->reverse[idx].lower_first)
            return -EINVAL;
        if (map->forward[idx].count != map->reverse[idx].count)
            return -EINVAL;
    }

    return 0;
}
```

The patch specifically addressed the inconsistent ID transformation that occurred when the kernel needed to map IDs back from the global namespace to the user namespace (reverse direction) with more than 5 ranges configured. The fix ensured proper bidirectional mapping consistency in nested user namespace scenarios.

